var P=[
[1,"Sữa tươi 1L","🥛","sua",32000,"Sữa tươi tiệt trùng TH true MILK có đường, hộp 1 lít. Vị béo nhẹ, dễ uống."],
[2,"Trứng gà (10 quả)","🥚","sua",35000,"Trứng gà tươi, vỏ sạch, lòng đỏ đậm. Hộp 10 quả."],
[3,"Sữa chua uống","🍶","sua",28000,"Sữa chua uống hương cam, bổ sung canxi và vitamin C. Chai nhỏ, hợp cho bé."],
[4,"Cà chua 500g","🍅","rau",18000,"Cà chua chín mọng, dùng cho salad, nấu canh hoặc làm sốt."],
[5,"Rau muống","🥬","rau",12000,"Rau muống tươi, nhặt sạch. Bó khoảng 400g."],
[6,"Cà rốt 500g","🥕","rau",15000,"Cà rốt ngọt giòn, hợp xào, hầm và ép nước."],
[7,"Nước suối 1.5L","💧","nuoc",8000,"Nước uống tinh khiết đóng chai 1,5 lít, dùng hằng ngày."],
[8,"Nước cam ép","🍊","nuoc",25000,"Nước cam ép vị cam thơm mát, ngon nhất khi uống lạnh. Chai lớn, hợp dùng cho cả gia đình."],
[9,"Trà xanh","🍵","nuoc",12000,"Trà xanh Không Độ vị chanh, thanh mát, ngon nhất khi uống lạnh."],
[10,"Bánh quy bơ","🍪","banh",22000,"Bánh quy bơ sữa giòn thơm, ngon khi chấm sữa, trà hoặc socola nóng."],
[11,"Socola thanh","🍫","banh",30000,"Socola đen 70% dạng thanh, vị đậm đà, hơi đắng nhẹ."],
[12,"Snack khoai tây","🥔","banh",15000,"Snack khoai tây lát gợn sóng giòn rụm, vị bít tết kiểu New York."]];
var CATS={sua:"Sữa & trứng",rau:"Rau củ",nuoc:"Đồ uống",banh:"Bánh kẹo"};
var IMG={12:"data:image/jpeg;base64,",11:"data:image/jpeg;base64,",9:"data:image/jpeg;base64,",7:"data:image/jpeg;base64,",6:"data:image/jpeg;base64,",5:"data:image/jpeg;base64,",3:"data:image/jpeg;base64,",2:"data:image/jpeg;base64,",10:"data:image/jpeg;base64,",8:"data:image/jpeg;base64,",4:"data:image/jpeg;base64,",1:"data:image/jpeg;base64,"};
function pic(p,sm){return IMG[p[0]]?'<img '+(sm?'class="th" ':'')+'src="'+IMG[p[0]]+'" alt="'+p[1]+'">':p[2]}
var CIMG={banh:"data:image/jpeg;base64,",nuoc:"data:image/jpeg;base64,",rau:"data:image/jpeg;base64,",sua:"data:image/jpeg;base64,"};
var cart={},cat="all",dq=1,loggedIn=false,tt,SHIP=15000;
var $=function(i){return document.getElementById(i)};
var fmt=function(n){return n.toLocaleString("vi-VN")+"đ"};
function toast(m){var t=$("toast");t.textContent=m;t.classList.add("on");clearTimeout(tt);tt=setTimeout(function(){t.classList.remove("on")},2200)}
function badge(){var n=0;for(var k in cart)n+=cart[k];$("cb").textContent=n}
function addCart(id,n){cart[id]=(cart[id]||0)+n;badge();toast("Đã thêm "+n+" × "+P[id-1][1]+" vào giỏ hàng")}
function card(p){return '<div class="card"><a class="pimg" href="#/product/'+p[0]+'" aria-label="'+p[1]+'">'+pic(p)+'</a><p class="pname">'+p[1]+'</p><p class="price">'+fmt(p[4])+'</p><div class="act"><a class="btn line" href="#/product/'+p[0]+'">Chi tiết</a><button class="btn" onclick="addCart('+p[0]+',1)">Thêm</button></div></div>'}

/* ---------- Trang chủ ---------- */
function home(){
var c="";for(var k in CATS)c+='<a class="card cat" href="#/products" onclick="cat=\''+k+'\'"><img src="'+CIMG[k]+'" alt="">'+CATS[k]+'</a>';
return '<section class="hero"><div><h1>Mua sắm nhanh,<br>giao tận nhà.</h1><p>Rau củ, sữa, đồ uống và bánh kẹo tươi mới mỗi ngày, chọn trong vài giây.</p><a class="btn" href="#/products" onclick="cat=\'all\'">Xem sản phẩm</a></div><div class="big">🛒</div></section>'+
'<h2>Danh mục</h2><div class="grid">'+c+'</div><h2>Sản phẩm nổi bật</h2><div class="grid">'+[1,4,8,10].map(function(i){return card(P[i-1])}).join("")+'</div>'+
'<section class="promo"><div><h3>Khuyến mãi tuần này</h3><p>Giảm 10% cho đơn từ 200.000đ.</p></div><a class="btn" href="#/member">Xem ưu đãi</a></section>';
}

/* ---------- Danh sách sản phẩm ---------- */
function products(){
var b='<button data-c="all" onclick="setCat(\'all\')">Tất cả</button>';for(var k in CATS)b+='<button data-c="'+k+'" onclick="setCat(\''+k+'\')">'+CATS[k]+'</button>';
return '<h2 style="margin-top:32px">Tất cả sản phẩm</h2><input id="q" placeholder="Tìm theo tên sản phẩm…" oninput="drawGrid()" aria-label="Tìm sản phẩm"><div class="chips">'+b+'</div><div class="grid" id="grid"></div><p id="none" class="muted" style="display:none;padding:24px 0">Không tìm thấy sản phẩm.</p>';
}
function setCat(c){cat=c;drawGrid()}
function drawGrid(){
var k=$("q").value.trim().toLowerCase(),r=P.filter(function(p){return(cat=="all"||p[3]==cat)&&p[1].toLowerCase().indexOf(k)>-1});
$("grid").innerHTML=r.map(card).join("");$("none").style.display=r.length?"none":"block";
document.querySelectorAll(".chips button").forEach(function(b){b.classList.toggle("on",b.dataset.c==cat)});
}

/* ---------- Chi tiết sản phẩm ---------- */
function detail(id){
var p=P[id-1]||P[0];dq=1;
return '<a class="back" href="#/products">← Quay lại danh sách</a><div class="two"><div class="pimg" style="font-size:140px">'+pic(p)+'</div><div><span class="tag">Còn hàng</span><h1 style="font-size:34px;margin:10px 0 6px">'+p[1]+'</h1><p class="price" style="font-size:26px">'+fmt(p[4])+'</p><p>'+p[5]+'</p>'+
'<div class="qty"><button class="qb" onclick="chgQ(-1)" aria-label="Giảm">−</button><output id="dq">1</output><button class="qb" onclick="chgQ(1)" aria-label="Tăng">+</button></div><button class="btn" onclick="addCart('+p[0]+',dq)">Thêm vào giỏ</button></div></div>'+
'<div class="card" style="margin-top:40px;max-width:560px"><h3>Thông tin thêm</h3><table><tr><td>Danh mục</td><td>'+CATS[p[3]]+'</td></tr><tr><td>Bảo quản</td><td>Nơi khô mát, tránh ánh nắng trực tiếp</td></tr><tr><td>Giao hàng</td><td>Trong ngày với đơn đặt trước 17h</td></tr></table></div>';
}
function chgQ(d){dq=Math.min(10,Math.max(1,dq+d));$("dq").textContent=dq}

/* ---------- Giỏ hàng & đặt hàng ---------- */
function cartView(){
return '<h2 style="margin-top:32px">Giỏ hàng của bạn</h2><p id="empty" class="muted" style="display:none;text-align:center;padding:56px 0">Giỏ hàng của bạn đang trống.<br><br><a class="btn line" href="#/products">Tiếp tục mua sắm</a></p>'+
'<div id="box" class="two wide"><div class="card scroll"><table><thead><tr><th>Sản phẩm</th><th>Đơn giá</th><th>Số lượng</th><th>Thành tiền</th><th></th></tr></thead><tbody id="rows"></tbody></table></div>'+
'<div><div class="card"><div class="row"><span>Tạm tính</span><span id="sum"></span></div><div class="row"><span>Phí giao hàng</span><span id="ship"></span></div><div class="row total"><span>Tổng tiền</span><span id="tot"></span></div></div>'+
'<div class="card" style="margin-top:18px" id="formBox"><h3>Thông tin nhận hàng</h3><label for="name">Họ tên</label><input id="name"><label for="phone">Số điện thoại</label><input id="phone" inputmode="numeric"><label for="addr">Địa chỉ</label><input id="addr"><p id="err" class="err"></p><button class="btn" style="width:100%" onclick="order()">Đặt hàng</button></div></div></div>';
}
function drawCart(){
var ids=Object.keys(cart).filter(function(k){return cart[k]>0}),s=0;
$("rows").innerHTML=ids.map(function(k){var p=P[k-1],t=p[4]*cart[k];s+=t;
return '<tr><td>'+pic(p,1)+' '+p[1]+'</td><td>'+fmt(p[4])+'</td><td><button class="qb" onclick="cq('+k+',-1)">−</button> <span>'+cart[k]+'</span> <button class="qb" onclick="cq('+k+',1)">+</button></td><td>'+fmt(t)+'</td><td><button class="del" onclick="delItem('+k+')">Xóa</button></td></tr>'}).join("");
$("sum").textContent=fmt(s);$("ship").textContent=fmt(ids.length?SHIP:0);$("tot").textContent=fmt(ids.length?s+SHIP:0);
$("empty").style.display=ids.length?"none":"block";$("box").style.display=ids.length?"":"none";badge();
}
function cq(id,d){cart[id]=Math.max(1,cart[id]+d);drawCart()}
function delItem(id){delete cart[id];drawCart()}
function order(){
var n=$("name").value.trim(),p=$("phone").value.trim(),a=$("addr").value.trim(),e=$("err");
if(!n||!p||!a){e.textContent="Vui lòng nhập đủ họ tên, số điện thoại và địa chỉ.";return}
if(!/^[0-9]{10}$/.test(p)){e.textContent="Số điện thoại phải gồm đúng 10 chữ số.";return}
cart={};badge();
$("box").innerHTML='<div class="card" style="grid-column:1/-1"><h3 class="ok" style="font-size:20px">Đặt hàng thành công!</h3><p class="muted">Cảm ơn '+n.replace(/</g,"&lt;")+'. MiniMart sẽ gọi xác nhận trong ít phút.</p><br><a class="btn" href="#/products">Tiếp tục mua sắm</a></div>';
}

/* ---------- Hội viên & Ưu đãi ---------- */
function member(){
return '<h2 style="margin-top:32px">Ưu đãi chung</h2><div class="grid3"><div class="card offer"><h3>Giảm 10%</h3><p>Cho đơn hàng từ 200.000đ.</p></div><div class="card offer"><h3>Miễn phí giao hàng</h3><p>Cho đơn từ 500.000đ trong bán kính 5 km.</p></div><div class="card offer"><h3>Mua 2 tặng 1</h3><p>Áp dụng cho nhóm bánh kẹo vào cuối tuần.</p></div></div>'+
'<section id="guest"><h2>Trở thành hội viên MiniMart</h2><div class="two"><div><h3>Quyền lợi</h3><p class="muted">Tích 1 điểm cho mỗi 10.000đ, đổi điểm thành quà, nhận ưu đãi riêng theo hạng và xem lại lịch sử mua hàng.</p></div>'+
'<div class="card"><label for="mn">Họ tên (khi đăng ký)</label><input id="mn"><label for="em">Email</label><input id="em" autocomplete="email"><label for="pw">Mật khẩu</label><input id="pw" type="password"><p id="msg" class="err"></p><div class="acts"><button class="btn line" onclick="reg()">Đăng ký</button><button class="btn" onclick="login()">Đăng nhập</button></div></div></div></section>'+
'<section id="mem" style="display:none"><h2>Xin chào, Nguyễn Văn An</h2><div class="badges"><div class="badge"><b>1.250</b>Điểm tích lũy</div><div class="badge"><b>Hạng Bạc</b>Còn 750 điểm lên Vàng</div></div>'+
'<h2>Ưu đãi riêng cho bạn</h2><div class="grid3"><div class="card offer"><h3>Giảm 15% rau củ</h3><p>Dùng đến hết tháng này.</p></div><div class="card offer"><h3>Tặng 100 điểm</h3><p>Cho đơn đầu tiên trong tuần.</p></div><div class="card offer"><h3>Sữa tươi giá hội viên</h3><p>Chỉ 29.000đ/lít.</p></div></div>'+
'<h2>Lịch sử mua hàng</h2><div class="card scroll"><table><thead><tr><th>Ngày</th><th>Mã đơn</th><th>Tổng tiền</th><th>Điểm</th></tr></thead><tbody><tr><td>05/10/2026</td><td>MM1042</td><td>186.000đ</td><td>+18</td></tr><tr><td>28/09/2026</td><td>MM1017</td><td>94.000đ</td><td>+9</td></tr><tr><td>15/09/2026</td><td>MM0983</td><td>312.000đ</td><td>+31</td></tr></tbody></table></div>'+
'<div class="acts" style="max-width:420px"><a class="btn line" href="#/products">Mua sắm</a><a class="btn line" href="#/cart">Giỏ hàng</a><button class="btn" onclick="logout()">Đăng xuất</button></div></section>';
}
function chk(reg){
var m=$("msg"),v=function(i){return $(i).value.trim()};m.className="err";
if(reg&&!v("mn")){m.textContent="Vui lòng nhập họ tên.";return false}
if(v("em").indexOf("@")<1){m.textContent="Email không hợp lệ (cần có ký tự @).";return false}
if(!v("pw")){m.textContent="Vui lòng nhập mật khẩu.";return false}
m.textContent="";return true}
function reg(){if(chk(true)){$("msg").className="ok";$("msg").textContent="Đăng ký thành công! Bạn có thể đăng nhập ngay."}}
function login(){if(chk(false)){loggedIn=true;showMember()}}
function logout(){loggedIn=false;showMember()}
function showMember(){$("guest").style.display=loggedIn?"none":"block";$("mem").style.display=loggedIn?"block":"none"}

/* ---------- Điều hướng ---------- */
function route(){
var a=(location.hash.slice(2)||"home").split("/"),v=a[0],views={home:home,products:products,product:function(){return detail(+a[1]||1)},cart:cartView,member:member};
if(!views[v])v="home";
$("app").innerHTML=views[v]();
if(v=="products")drawGrid();if(v=="cart")drawCart();if(v=="member")showMember();
var cur=v=="product"?"products":v;
document.querySelectorAll("nav a").forEach(function(l){l.classList.toggle("on",l.dataset.v==cur)});
$("menu").classList.remove("open");window.scrollTo(0,0);
}
window.addEventListener("hashchange",route);route();
